(()=>{'use strict';
window.createSubtitleWorkspace=function({api,video,onClose=()=>{}}){const element=document.createElement('section');element.className='subtitle-workspace';element.setAttribute('aria-label','Subtitle manager');element.innerHTML='<div class="sw-heading"><div><h2>Subtitles</h2><p data-movie></p></div><button type="button" data-close aria-label="Close subtitles">Close</button></div><div class="sw-current"><span data-current>Subtitles off</span><button type="button" data-off>Turn off</button></div><section><h3>Saved with this video</h3><div data-local></div></section><section><h3>Find online</h3><form><label>Video title or ID<input name="query" type="search" maxlength="200" required autocomplete="off"></label><label>Language<select name="language"><option value="en">English</option><option value="zh-hans">Chinese Simplified</option><option value="zh-hant">Chinese Traditional</option><option value="zh">Chinese</option><option value="ja">Japanese</option><option value="ko">Korean</option><option value="fr">French</option><option value="es">Spanish</option><option value="de">German</option><option value="pt">Portuguese</option><option value="th">Thai</option><option value="vi">Vietnamese</option><option value="id">Indonesian</option><option value="ar">Arabic</option><option value="ru">Russian</option><option value="all">All languages</option></select></label><button type="submit" data-search>Search subtitles</button></form><p class="sw-note">Searches SubtitleCat. Download & apply saves a new subtitle beside the video, without replacing existing files.</p><div data-results></div></section><p class="sw-status" role="status" aria-live="polite"></p>';
const find=s=>element.querySelector(s);const form=find('form');let movieId=null,source=null,generation=0,busy=false,track=null,blob=null,appliedName='';
const status=text=>find('[role=status]').textContent=text;
function buttonsDisabled(value){busy=value;for(const control of element.querySelectorAll('button:not([data-close]):not([data-off]),input,select'))control.disabled=value;}
function clearOwn(){if(track){track.remove();track=null;}if(blob){URL.revokeObjectURL(blob);blob=null;}}function off(){clearOwn();for(const item of Array.from(video.textTracks))item.mode='disabled';appliedName='';find('[data-current]').textContent='Subtitles off';}
function apply(result){off();for(const item of video.textTracks)item.mode='disabled';blob=URL.createObjectURL(new Blob([result.content],{type:'text/vtt'}));track=document.createElement('track');track.kind='subtitles';track.label=result.name||result.language||'Downloaded subtitle';track.srclang=result.language||'und';track.src=blob;track.default=true;track.dataset.subtitleWorkspace='';video.append(track);track.track.mode='showing';track.addEventListener('load',()=>{if(track)track.track.mode='showing';});appliedName=track.label;find('[data-current]').textContent='Active: '+appliedName;}
async function locals(current){const data=await api.state(current);if(current!==movieId)return;find('[data-local]').replaceChildren();if(!data.subtitles.length){const text=document.createElement('p');text.className='sw-note';text.textContent='No saved SRT or VTT subtitles yet.';find('[data-local]').append(text);}for(const subtitle of data.subtitles){const row=document.createElement('div');row.className='sw-row';const label=document.createElement('span');label.textContent=subtitle.name+' · '+subtitle.language;const button=document.createElement('button');button.type='button';button.textContent='Use subtitle';button.onclick=async()=>{if(busy)return;const version=generation;buttonsDisabled(true);status('Loading saved subtitle…');try{const result=await api.local(current,subtitle.id);if(version!==generation||video.currentSrc!==source)return;apply(result);status('Saved subtitle applied. Playback continues.');}catch(error){if(version===generation)status(error.message);}finally{if(version===generation)buttonsDisabled(false);}};row.append(label,button);find('[data-local]').append(row);}return data;}
async function open(id){const changed=movieId!==id||source!==video.currentSrc;if(changed){clearOwn();const active=Array.from(video.textTracks).find(t=>t.mode==='showing');find('[data-current]').textContent=active?'Active: '+(active.label||active.language||'Saved subtitle'):'Subtitles off';movieId=id;source=video.currentSrc;generation++;buttonsDisabled(false);find('[data-results]').replaceChildren();}element.hidden=false;status('Loading subtitles…');const version=generation;try{const data=await locals(id);if(!data||version!==generation)return;find('[data-movie]').textContent=data.title;if(changed||!form.elements.query.value)form.elements.query.value=data.query;status('Choose a saved subtitle, or search online.');}catch(error){status(error.message);}}
form.onsubmit=async event=>{event.preventDefault();if(busy||!movieId)return;const current=movieId,version=generation;buttonsDisabled(true);find('[data-results]').replaceChildren();status('Searching SubtitleCat…');try{const language=form.elements.language.value;try{localStorage.setItem('mla-subtitle-language',language);}catch{}const results=await api.search(current,form.elements.query.value.trim(),language);if(version!==generation||video.currentSrc!==source)return;status(results.length?results.length+' matching subtitle'+(results.length===1?'':'s')+'. Choose one to download and apply.':'No matching subtitles. Try another title, ID, or language.');for(const result of results){const row=document.createElement('div');row.className='sw-row';const details=document.createElement('div');const title=document.createElement('strong');title.textContent=result.title;const meta=document.createElement('small');meta.textContent=result.language+(result.downloads?' · '+result.downloads+' downloads':'');details.append(title,meta);const button=document.createElement('button');button.type='button';button.textContent='Download & apply';button.onclick=async()=>{if(busy)return;buttonsDisabled(true);status('Downloading subtitle…');try{const subtitle=await api.download(current,result.id);if(version!==generation||video.currentSrc!==source)return;apply(subtitle);await locals(current);status(subtitle.saved?'Downloaded, saved, and applied. Playback continues.':subtitle.warning||'Applied for this session.');}catch(error){if(version===generation)status(error.message);}finally{if(version===generation)buttonsDisabled(false);}};row.append(details,button);find('[data-results]').append(row);}}catch(error){if(version===generation)status('Search failed: '+error.message);}finally{if(version===generation)buttonsDisabled(false);}};
find('[data-close]').onclick=onClose;find('[data-off]').onclick=()=>{off();status('Subtitles turned off.');};form.elements.language.onchange=()=>{find('[data-results]').replaceChildren();status('Language changed. Search again to refresh results.');};try{const language=localStorage.getItem('mla-subtitle-language');if([...form.elements.language.options].some(o=>o.value===language))form.elements.language.value=language;}catch{}
video.addEventListener('loadstart',()=>{if(source&&source!==video.currentSrc){generation++;movieId=null;source=null;clearOwn();element.hidden=true;onClose();}});
return{element,open,off,destroy:()=>{off();element.remove();}};};})();
